const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{--bigsz:22px;box-sizing:border-box;width:100%;height:100%;min-width:0;min-height:0;padding:8px;display:flex;flex-direction:column;overflow:hidden;background:transparent;color:var(--ink);font-size:12px;line-height:1.35}\n.card *{box-sizing:border-box}\n.card[data-size=\"6x3\"]{--bigsz:22px;padding:10px}\n.card[data-size=\"3x6\"]{--bigsz:26px;padding:10px}\n.card[data-size=\"6x6\"]{--bigsz:34px;padding:12px;font-size:13px}\n.view{flex:1;min-height:0;min-width:0;display:grid;gap:6px}\n.card button{font:inherit;color:inherit;margin:0}\n.bar{display:flex;align-items:center;gap:6px;min-height:28px;min-width:0}\n.ttl{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:700;font-size:1.1em}\n.cnt{color:var(--muted);font-size:11px;white-space:nowrap}\n.ico{flex:none;width:28px;height:28px;border:1px solid var(--line);border-radius:8px;background:var(--button-paper,var(--panel-paper));color:var(--ink);cursor:pointer;font-size:16px;line-height:1;padding:0}\n.btn{border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);border-radius:8px;padding:0 10px;min-height:30px;cursor:pointer;white-space:nowrap}\n.btn.sm{min-height:26px;padding:0 8px;font-size:11px}\n.btn.pri{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:600}\n.btn.dng{color:#D1493F;border-color:#D1493F;background:transparent}\n.btn.grow{flex:1}\n.btn:disabled{opacity:.5;cursor:default}\n.card button:focus-visible,.card input:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.v-list{grid-template-rows:auto minmax(0,1fr);grid-template-columns:minmax(0,1fr)}\n.plans{overflow:auto;min-height:0;min-width:0;display:grid;gap:6px;align-content:start;overscroll-behavior:contain}\n.card[data-size=\"6x3\"] .plans,.card[data-size=\"6x6\"] .plans{grid-template-columns:repeat(auto-fill,minmax(170px,1fr))}\n.pcard{display:grid;gap:1px;min-width:0;text-align:left;border:1px solid var(--line);background:var(--panel-paper);border-radius:10px;padding:7px 9px;color:var(--ink);cursor:pointer}\n.pn{min-width:0;font-weight:600;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;word-break:break-word}\n.pv{font-weight:700;color:var(--accent);font-variant-numeric:tabular-nums;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:1.15em}\n.pm{color:var(--muted);font-size:10.5px}\n.zero{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;text-align:center;min-height:0;padding:4px}\n.zt{font-weight:700;font-size:1.15em}\n.zs{color:var(--muted);font-size:11px}\n\n.v-plan{grid-template-columns:minmax(0,1fr);grid-template-rows:auto auto minmax(0,1fr) auto;grid-template-areas:\"head\" \"sum\" \"lists\" \"adds\"}\n.v-plan>.bar{grid-area:head}\n.v-plan>.sum{grid-area:sum}\n.v-plan>.lists{grid-area:lists}\n.v-plan>.adds{grid-area:adds}\n.sum{display:grid;gap:6px;min-width:0;padding:7px 10px;border-radius:12px;background:var(--soft);border:1px solid var(--line)}\n.lbl{color:var(--muted);font-size:11px}\n.big{font-size:var(--bigsz);font-weight:700;line-height:1.15;color:var(--accent);font-variant-numeric:tabular-nums;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.big.m{font-size:calc(var(--bigsz)*.84)}\n.big.s{font-size:calc(var(--bigsz)*.7)}\n.mix{display:flex;height:6px;border-radius:3px;overflow:hidden;background:var(--line)}\n.ma{background:var(--accent)}\n.mb{background:var(--accent-alt)}\n.brk{display:grid;gap:2px;margin-top:5px}\n.bk{display:flex;align-items:center;gap:6px;min-width:0;font-size:11px}\n.bn{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--muted)}\n.bv{white-space:nowrap;font-variant-numeric:tabular-nums;font-weight:600}\n.dot{flex:none;width:8px;height:8px;border-radius:50%;background:var(--accent)}\n.dot.b{background:var(--accent-alt)}\n.lists{min-height:0;min-width:0;overflow-y:auto;overscroll-behavior:contain;display:flex;flex-direction:column;gap:8px}\n.sec{flex:none;min-width:0;display:flex;flex-direction:column}\n.sh{display:flex;align-items:center;gap:6px;padding:2px 2px 4px;font-weight:600;font-size:11px;color:var(--muted)}\n.sn{flex:none}\n.sv{margin-left:auto;color:var(--ink);font-variant-numeric:tabular-nums;white-space:nowrap}\n.sh .btn{margin-left:4px}\n.rows{display:flex;flex-direction:column;min-width:0}\n.row{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px;align-items:center;text-align:left;width:100%;min-height:36px;padding:5px 4px;border:0;border-top:1px solid var(--line);background:transparent;color:var(--ink);cursor:pointer}\n.rl{display:grid;min-width:0}\n.rn{min-width:0;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;word-break:break-word;font-weight:500}\n.rm{color:var(--muted);font-size:10.5px}\n.rv{font-weight:600;white-space:nowrap;font-variant-numeric:tabular-nums}\n.empty{padding:8px 4px;color:var(--muted);font-size:11px;border-top:1px solid var(--line)}\n.adds{display:grid;grid-template-columns:1fr 1fr;gap:6px}\n.adds .btn{padding:0 4px;min-height:30px}\n.card[data-size=\"3x3\"] .brk,.card[data-size=\"3x3\"] .mix,.card[data-size=\"3x3\"] .lbl{display:none}\n.card[data-size=\"3x3\"] .sum{padding:5px 9px;gap:0}\n.card[data-size=\"3x3\"] .big{font-size:calc(var(--bigsz)*.9)}\n.card[data-size=\"3x3\"] .big.m{font-size:calc(var(--bigsz)*.76)}\n.card[data-size=\"3x3\"] .big.s{font-size:calc(var(--bigsz)*.63)}\n.card[data-size=\"3x3\"] .lbl{display:block;font-size:10px}\n.card[data-size=\"6x3\"] .v-plan{grid-template-columns:168px minmax(0,1fr);grid-template-rows:auto auto minmax(0,1fr);grid-template-areas:\"head head\" \"sum lists\" \"adds lists\";column-gap:8px}\n.card[data-size=\"6x3\"] .adds{align-self:start}\n.card[data-size=\"6x3\"] .mix{display:none}\n.card[data-size=\"6x3\"] .brk{margin-top:0}\n.card[data-size=\"6x6\"] .sum{grid-template-columns:minmax(0,1fr) minmax(0,1fr);align-items:center;gap:14px;padding:10px 14px}\n.card[data-size=\"6x6\"] .brk{margin-top:6px}\n.card[data-size=\"6x6\"] .v-plan{grid-template-rows:auto auto minmax(0,1fr);grid-template-areas:\"head\" \"sum\" \"lists\"}\n.card[data-size=\"6x6\"] .lists{overflow:hidden;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px}\n.card[data-size=\"6x6\"] .sec{min-height:0}\n.card[data-size=\"6x6\"] .rows{overflow-y:auto;min-height:0;flex:1;overscroll-behavior:contain}\n.v-form{grid-template-columns:minmax(0,1fr);grid-template-rows:auto minmax(0,1fr) auto}\n.fbody{overflow:auto;min-height:0;min-width:0;display:grid;gap:8px;align-content:start;padding:2px;overscroll-behavior:contain}\n.fld{display:grid;gap:3px;min-width:0}\n.fl{font-size:11px;color:var(--muted)}\n.inp{width:100%;min-width:0;height:32px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);padding:0 8px;font:inherit}\n.two{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:6px}\n.fsub{font-weight:600;font-variant-numeric:tabular-nums;color:var(--accent)}\n.err{color:#D1493F;font-size:11px;word-break:break-word}\n.err:empty{display:none}\n.warn{font-size:11px;word-break:break-word}\n.ffoot{display:flex;gap:6px}\n.card[data-size=\"3x3\"] .inp{height:28px}\n.card[data-size=\"3x3\"] .fbody{gap:6px}\n.card[data-size=\"6x6\"] .fbody,.card[data-size=\"6x3\"] .fbody{max-width:420px;width:100%;margin:0 auto}\n";
function round2(x){return Math.round(x*100+1e-6)/100;}
function commas(n){return String(n).replace(/\B(?=(\d{3})+(?!\d))/g,',');}
function money(n){
  const c=Math.round(Math.abs(n)*100+1e-6);
  const f=c%100;
  return (n<0?'-':'')+'¥'+commas(Math.floor(c/100))+'.'+(f<10?'0':'')+f;
}
function rateText(n){
  const c=Math.round(n*100+1e-6);
  return c%100===0?'¥'+commas(c/100):money(n);
}
function numText(n){return String(Math.round(n*100)/100);}
function parseNum(v){
  const t=String(v==null?'':v).replace(/[,，\s]/g,'');
  if(!t)return NaN;
  const n=Number(t);
  return Number.isFinite(n)?n:NaN;
}
function lineAmt(it){return round2((Number(it.hours)||0)*(Number(it.rate)||0));}
function totals(p){
  const L=Array.isArray(p.labor)?p.labor:[];
  const C=Array.isArray(p.costs)?p.costs:[];
  let labor=0,hours=0,cost=0;
  L.forEach(i=>{labor+=lineAmt(i);hours+=Number(i.hours)||0;});
  C.forEach(i=>{cost+=round2(Number(i.amount)||0);});
  labor=round2(labor);
  cost=round2(cost);
  return {labor:labor,cost:cost,hours:hours,total:round2(labor+cost),nl:L.length,nc:C.length};
}
function lenCls(t){return t.length>=13?' s':t.length>=11?' m':'';}
function plansOf(s){return Array.isArray(s&&s.plans)?s.plans:[];}
function mapPlan(s,pid,fn){
  return Object.assign({},s,{plans:plansOf(s).map(p=>p.id===pid?fn(p):p)});
}

function mount(ctx){
  const {root,el,state,ui,commit,redraw,uid,size}=ctx;
  const plans=plansOf(state);
  if(!ui.view)ui.view='list';
  const plan=plans.find(p=>p.id===ui.pid)||null;
  if(ui.view!=='list'&&ui.view!=='new'&&!plan){ui.view='list';ui.pid=null;}
  if(!ui.draft)ui.draft={};
  const wide=size==='6x6';

  function go(view,extra){
    ui.view=view;ui.confirmDel=false;ui.saving=false;
    if(extra)Object.keys(extra).forEach(k=>{ui[k]=extra[k];});
    redraw();
  }
  function nx(view,extra){
    return Object.assign({view:view,pid:ui.pid,draft:{},eid:null,saving:false,confirmDel:false},extra||{});
  }
  function fail(err,msg){err.textContent='⚠ '+msg;return false;}
  function persist(fn,next,err){
    if(ui.saving)return;
    ui.saving=true;
    commit(fn,next).then(()=>{},e=>{
      ui.saving=false;
      err.textContent='⚠ 保存失败：'+(e&&e.message?e.message:'请重试');
    });
  }

  function openNew(){go('new',{draft:{name:''},eid:null});}
  function openItem(kind,it){
    const d=kind==='labor'
      ?{name:it?it.name:'',hours:it?String(it.hours):'',rate:it?String(it.rate):''}
      :{name:it?it.name:'',amount:it?String(it.amount):''};
    go(kind,{draft:d,eid:it?it.id:null});
  }
  function openMenu(){go('menu',{draft:{name:plan.name}});}

  function checkName(name,err,max){
    if(!name)return fail(err,'请填写名称');
    if(name.length>max)return fail(err,'名称请控制在 '+max+' 字以内');
    return true;
  }
  function createPlan(err){
    const name=String(ui.draft.name||'').trim();
    if(!checkName(name,err,30))return;
    const id=uid();
    persist(s=>Object.assign({},s,{plans:plansOf(s).concat([{id:id,name:name,labor:[],costs:[]}])}),nx('plan',{pid:id}),err);
  }
  function renamePlan(err){
    const name=String(ui.draft.name||'').trim();
    if(!checkName(name,err,30))return;
    const pid=ui.pid;
    persist(s=>mapPlan(s,pid,p=>Object.assign({},p,{name:name})),nx('plan'),err);
  }
  function copyPlan(err){
    const nid=uid(),pid=ui.pid;
    persist(s=>{
      const src=plansOf(s).find(p=>p.id===pid);
      if(!src)return s;
      const re=i=>Object.assign({},i,{id:uid()});
      const copy={id:nid,name:src.name+' 副本',labor:(src.labor||[]).map(re),costs:(src.costs||[]).map(re)};
      return Object.assign({},s,{plans:plansOf(s).concat([copy])});
    },nx('plan',{pid:nid}),err);
  }
  function deletePlan(err){
    const pid=ui.pid;
    persist(s=>Object.assign({},s,{plans:plansOf(s).filter(p=>p.id!==pid)}),nx('list',{pid:null}),err);
  }
  function saveItem(kind,err){
    const d=ui.draft||{};
    const name=String(d.name||'').trim();
    if(!checkName(name,err,40))return;
    let rec;
    if(kind==='labor'){
      const h=parseNum(d.hours),r=parseNum(d.rate);
      if(!(h>=0&&h<=100000))return fail(err,'预计工时请填 0 到 100000 小时');
      if(!(r>=0&&r<=10000000))return fail(err,'时薪请填不小于 0 的金额');
      rec={id:ui.eid||uid(),name:name,hours:Math.round(h*100)/100,rate:Math.round(r*100)/100};
    }else{
      const a=parseNum(d.amount);
      if(!(a>=0&&a<=10000000000))return fail(err,'金额请填不小于 0 的数字');
      rec={id:ui.eid||uid(),name:name,amount:Math.round(a*100)/100};
    }
    const key=kind==='labor'?'labor':'costs';
    const isNew=!ui.eid,pid=ui.pid;
    persist(s=>mapPlan(s,pid,p=>{
      const list=Array.isArray(p[key])?p[key]:[];
      const next=isNew?list.concat([rec]):list.map(i=>i.id===rec.id?rec:i);
      return Object.assign({},p,{[key]:next});
    }),nx('plan'),err);
  }
  function deleteItem(kind,err){
    const key=kind==='labor'?'labor':'costs';
    const id=ui.eid,pid=ui.pid;
    persist(s=>mapPlan(s,pid,p=>Object.assign({},p,{[key]:(p[key]||[]).filter(i=>i.id!==id)})),nx('plan'),err);
  }


  function listView(){
    const kids=[el('div',{class:'ttl'},'报价方案')];
    if(plans.length){
      kids.push(el('span',{class:'cnt'},String(plans.length)+' 个'));
      kids.push(el('button',{class:'btn pri sm',type:'button',onclick:openNew},'＋ 新建'));
    }
    const bar=el('div',{class:'bar'},...kids);
    let body;
    if(!plans.length){
      body=el('div',{class:'zero'},
        el('div',{class:'zt'},'还没有报价方案'),
        el('div',{class:'zs'},'每个方案独立保存，随时回来修改'),
        el('button',{class:'btn pri',type:'button',onclick:openNew},'新建第一个方案'));
    }else{
      body=el('div',{class:'plans'},...plans.map(p=>{
        const t=totals(p);
        return el('button',{class:'pcard',type:'button',onclick:()=>go('plan',{pid:p.id}),'aria-label':'打开方案 '+p.name},
          el('span',{class:'pn'},p.name),
          el('span',{class:'pv'},money(t.total)),
          el('span',{class:'pm'},'人工 '+numText(t.hours)+' 小时 · 成本 '+t.nc+' 项'));
      }));
    }
    return el('div',{class:'view v-list'},bar,body);
  }

  function rowOf(kind,it){
    const isL=kind==='labor';
    const meta=isL?numText(it.hours)+' 小时 × '+rateText(it.rate)+'/时':'直接成本';
    const amt=isL?lineAmt(it):round2(Number(it.amount)||0);
    return el('button',{class:'row',type:'button',onclick:()=>openItem(kind,it),'aria-label':'编辑 '+it.name},
      el('span',{class:'rl'},el('span',{class:'rn'},it.name),el('span',{class:'rm'},meta)),
      el('span',{class:'rv'},money(amt)));
  }
  function section(kind,items,sub){
    const isL=kind==='labor';
    const hd=[el('span',{class:'dot '+(isL?'a':'b')}),el('span',{class:'sn'},isL?'人工':'直接成本'),el('span',{class:'sv'},money(sub))];
    if(wide)hd.push(el('button',{class:'btn sm',type:'button',onclick:()=>openItem(kind,null)},'＋ 添加'));
    const rows=items.length
      ?items.map(it=>rowOf(kind,it))
      :[el('div',{class:'empty'},isL?'暂无人工项':'暂无直接成本')];
    return el('section',{class:'sec'},el('div',{class:'sh'},...hd),el('div',{class:'rows'},...rows));
  }

  function planView(p){
    const t=totals(p);
    const head=el('div',{class:'bar'},
      el('button',{class:'ico',type:'button','aria-label':'返回方案列表',onclick:()=>go('list',{pid:null})},'‹'),
      el('div',{class:'ttl',title:p.name},p.name),
      el('button',{class:'ico',type:'button','aria-label':'方案设置',onclick:openMenu},'⋯'));
    const tt=money(t.total);
    const ma=el('span',{class:'ma'}),mb=el('span',{class:'mb'});
    const pa=t.total>0?t.labor/t.total*100:0;
    ma.style.width=pa+'%';
    mb.style.width=(t.total>0?100-pa:0)+'%';
    const bk=(cls,name,val)=>el('div',{class:'bk'},el('span',{class:'dot '+cls}),el('span',{class:'bn'},name),el('span',{class:'bv'},val));
    const sum=el('div',{class:'sum'},
      el('div',{class:'tot'},
        el('div',{class:'lbl'},'总报价（人民币）'),
        el('div',{class:'big'+lenCls(tt),title:tt},tt)),
      el('div',{class:'mixwrap'},
        el('div',{class:'mix','aria-hidden':'true'},ma,mb),
        el('div',{class:'brk'},
          bk('a','人工 · '+numText(t.hours)+' 小时',money(t.labor)),
          bk('b','直接成本',money(t.cost)))));
    const lists=el('div',{class:'lists'},
      section('labor',Array.isArray(p.labor)?p.labor:[],t.labor),
      section('costs',Array.isArray(p.costs)?p.costs:[],t.cost));
    const parts=[head,sum,lists];
    if(!wide){
      parts.push(el('div',{class:'adds'},
        el('button',{class:'btn pri',type:'button',onclick:()=>openItem('labor',null)},'＋ 人工'),
        el('button',{class:'btn pri',type:'button',onclick:()=>openItem('costs',null)},'＋ 直接成本')));
    }
    return el('div',{class:'view v-plan'},...parts);
  }


  function formShell(title,backTo,body,foot){
    const head=el('div',{class:'bar'},
      el('button',{class:'ico',type:'button','aria-label':'返回',onclick:backTo},'‹'),
      el('div',{class:'ttl'},title));
    return el('div',{class:'view v-form'},head,el('div',{class:'fbody'},...body),el('div',{class:'ffoot'},...foot));
  }
  function field(label,input){return el('label',{class:'fld'},el('span',{class:'fl'},label),input);}
  function textIn(key,ph,onEnter,onChange){
    return el('input',{class:'inp',type:'text',value:String(ui.draft[key]||''),placeholder:ph,
      oninput:e=>{ui.draft[key]=e.target.value;if(onChange)onChange();},
      onkeydown:e=>{if(e.key==='Enter')onEnter();}});
  }
  function numIn(key,ph,onEnter,onChange){
    return el('input',{class:'inp',type:'number',step:'any',min:'0',inputmode:'decimal',value:String(ui.draft[key]||''),placeholder:ph,
      oninput:e=>{ui.draft[key]=e.target.value;if(onChange)onChange();},
      onkeydown:e=>{if(e.key==='Enter')onEnter();}});
  }

  function itemForm(kind){
    const isL=kind==='labor',editing=!!ui.eid;
    const err=el('div',{class:'err',role:'alert'});
    const sub=el('div',{class:'fsub'});
    const sync=()=>{
      const d=ui.draft;
      let v;
      if(isL){const h=parseNum(d.hours),r=parseNum(d.rate);v=(h>=0&&r>=0)?round2(h*r):null;}
      else{const a=parseNum(d.amount);v=a>=0?round2(a):null;}
      sub.textContent='小计 '+(v==null?'—':money(v));
    };
    const save=()=>saveItem(kind,err);
    const body=[field(isL?'工作内容':'成本名称',textIn('name',isL?'如：方案设计':'如：材料费',save))];
    if(isL){
      body.push(el('div',{class:'two'},
        field('预计工时（小时）',numIn('hours','0',save,sync)),
        field('时薪（元/小时）',numIn('rate','0',save,sync))));
    }else{
      body.push(field('金额（元）',numIn('amount','0',save,sync)));
    }
    body.push(sub,err);
    sync();
    let foot;
    if(ui.confirmDel){
      body.push(el('div',{class:'warn'},'⚠ 删除后无法恢复，确定删除这一项？'));
      foot=[el('button',{class:'btn dng grow',type:'button',onclick:()=>deleteItem(kind,err)},'确认删除'),
        el('button',{class:'btn',type:'button',onclick:()=>{ui.confirmDel=false;redraw();}},'取消')];
    }else{
